			db.incrObjectFieldBy(`topic:${id}`, 'numThumbs', -toRemove.length),
			Promise.all(toRemove.map(async relativePath => posts.uploads.dissociate(mainPid, relativePath.replace('/files/', '')))),
		]);
	}
};

